"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Brain, Zap, Eye, MessageSquare, TrendingUp, Shield, BarChart3, Settings, User, LogOut, Plus, Calendar, Users } from "lucide-react";
import { useUser } from "@stackframe/stack";
import InterviewChatbot from "@/components/InterviewChatbot";

interface Interview {
  id: number;
  role: string;
  interview_type: string;
  experience_level: string;
  num_questions: number;
  questions: string[];
  responses: string[];
  feedback: object;
  created_at: string;
}

export default function DashboardPage() {
  const user = useUser();
  const router = useRouter();
  const [isScrolled, setIsScrolled] = useState(false);
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [chatbotOpen, setChatbotOpen] = useState(false);

  // Interview generation form state
  const [role, setRole] = useState("");
  const [interviewType, setInterviewType] = useState("");
  const [experienceLevel, setExperienceLevel] = useState("");
  const [numQuestions, setNumQuestions] = useState(5);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleSignOut = async () => {
    await user?.signOut();
    router.push("/");
  };

  // Redirect if not signed in
  useEffect(() => {
    if (!user) {
      router.push("/auth/signin");
    }
  }, [user, router]);

  // Fetch interviews on component mount
  useEffect(() => {
    fetchInterviews();
  }, []);

  const fetchInterviews = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/interviews/');
      if (response.ok) {
        const data = await response.json();
        setInterviews(data);
      }
    } catch (error) {
      console.error('Error fetching interviews:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateInterview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!role || !interviewType || !experienceLevel) {
      alert('Please fill in all fields');
      return;
    }

    setGenerating(true);
    try {
      const response = await fetch('/api/interviews/create/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          role,
          type: interviewType,
          level: experienceLevel,
          num_questions: numQuestions,
        }),
      });

      if (response.ok) {
        const newInterview = await response.json();
        setInterviews([newInterview, ...interviews]);
        // Reset form
        setRole("");
        setInterviewType("");
        setExperienceLevel("");
        setNumQuestions(5);
      } else {
        alert('Error generating interview');
      }
    } catch (error) {
      console.error('Error generating interview:', error);
      alert('Error generating interview');
    } finally {
      setGenerating(false);
    }
  };

  const handleInterviewGenerated = (interviewData: Interview) => {
    setInterviews([interviewData, ...interviews]);
    setChatbotOpen(false);
  };

  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 text-foreground font-sans">
      {/* Animated Background */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-purple-900/20 via-slate-900 to-slate-900 pointer-events-none"></div>
      <div className="fixed inset-0 bg-grid-white/[0.02] bg-[size:50px_50px] pointer-events-none"></div>

      {/* Navbar */}
      <nav
        className={`fixed w-full z-50 transition-all duration-300 ${
          isScrolled
            ? "bg-slate-900/80 backdrop-blur-md py-3 shadow-lg border-b border-purple-500/20"
            : "py-6"
        }`}
      >
        <div className="container mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center">
            <h1 className="text-2xl font-bold text-white">
              AI<span className="text-purple-400">NEX</span>
              <span className="text-xs inline-flex items-center bg-purple-500/10 backdrop-blur-sm border border-purple-500/20 rounded-full px-2 py-1 ml-2">
                Dashboard
              </span>
            </h1>
          </div>

          <div className="hidden lg:flex items-center space-x-4">
            <div className="flex items-center gap-2 text-gray-300">
              <User size={16} />
              <span>Welcome, {user.primaryEmail || "User"}</span>
            </div>
            <Button
              variant="outline"
              className="border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-white"
              onClick={() => router.push("/dashboard")}
            >
              Dashboard
            </Button>
            <Button
              variant="outline"
              className="border-gray-500 text-gray-400 hover:bg-gray-500 hover:text-white"
              onClick={handleSignOut}
            >
              <LogOut size={16} className="mr-2" />
              Sign Out
            </Button>
          </div>
        </div>
      </nav>

      {/* Floating Generate Interview Button */}
      <div className="fixed bottom-6 right-6 z-50">
        <Button
          className="h-14 w-14 rounded-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white shadow-lg animate-bounce-in"
          onClick={() => document.getElementById('generate-interview')?.scrollIntoView({ behavior: 'smooth' })}
        >
          <Plus className="size-6" />
        </Button>
      </div>

      <main className="relative z-10 pt-24 pb-12">
        <div className="container mx-auto px-6">
          {/* Welcome Section */}
          <section className="mb-12 animate-fade-in">
            <div className="text-center">
              <h1 className="font-display text-4xl md:text-6xl text-white mb-4">
                Welcome to your AI<span className="text-purple-400">NEX</span> Dashboard
              </h1>
              <p className="text-gray-300 text-xl max-w-2xl mx-auto">
                Monitor your AI usage, manage your models, and explore powerful features all in one place.
              </p>
            </div>
          </section>

          {/* Quick Actions */}
          <section className="mb-12 animate-fade-in">
            <Card className="p-8 bg-gradient-to-r from-purple-900/20 to-pink-900/20 border-purple-500/30">
              <CardHeader>
                <CardTitle className="text-white flex items-center gap-2 text-2xl">
                  <Zap className="size-8 text-purple-400" />
                  Quick Actions
                </CardTitle>
                <CardDescription className="text-gray-300 text-lg">
                  Fast access to your most used features
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                  <Button
                    className="h-20 bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white text-lg font-semibold animate-glow flex flex-col items-center gap-2"
                    onClick={() => setChatbotOpen(true)}
                  >
                    <Plus className="size-6" />
                    Generate Interview
                  </Button>
                  <Button className="h-20 bg-blue-600 hover:bg-blue-700 text-white text-lg flex flex-col items-center gap-2">
                    <Brain className="size-6" />
                    New AI Query
                  </Button>
                  <Button variant="outline" className="h-20 border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-white text-lg flex flex-col items-center gap-2">
                    <Settings className="size-6" />
                    Manage Models
                  </Button>
                  <Button variant="outline" className="h-20 border-gray-500 text-gray-400 hover:bg-gray-500 hover:text-white text-lg flex flex-col items-center gap-2">
                    <BarChart3 className="size-6" />
                    View Analytics
                  </Button>
                </div>
              </CardContent>
            </Card>
          </section>

          {/* Recent Interviews */}
          <section className="mb-12 animate-fade-in">
            <div className="flex items-center gap-2 mb-6">
              <Calendar className="size-6 text-purple-400" />
              <h2 className="text-3xl font-display text-white">Recent Interviews</h2>
            </div>
            {loading ? (
              <div className="text-center text-gray-400">Loading interviews...</div>
            ) : interviews.length > 0 ? (
              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {interviews.slice(0, 6).map((interview) => (
                  <Card key={interview.id} className="p-6 bg-slate-800/50 border-purple-500/20 hover:border-purple-500/40 transition-all animate-fade-in">
                    <CardHeader>
                      <CardTitle className="text-white text-lg">{interview.role}</CardTitle>
                      <CardDescription className="text-gray-300">
                        {interview.interview_type} • {interview.experience_level} • {interview.num_questions} questions
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <div className="text-gray-400 text-sm mb-4">
                        Created: {new Date(interview.created_at).toLocaleDateString()}
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          className="bg-purple-600 hover:bg-purple-700 text-white"
                          onClick={() => router.push(`/interview/${interview.id}`)}
                        >
                          View Questions
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-red-500 text-red-400 hover:bg-red-500 hover:text-white"
                          onClick={() => {
                            if (confirm('Are you sure you want to delete this interview?')) {
                              // Delete interview logic here
                            }
                          }}
                        >
                          Delete
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <div className="text-center text-gray-400 py-12">
                <MessageSquare className="size-16 text-gray-600 mx-auto mb-4" />
                <p className="text-xl">No interviews generated yet</p>
                <p className="text-gray-500">Create your first interview using the form above</p>
              </div>
            )}
          </section>

          {/* Community Interviews */}
          <section className="animate-fade-in">
            <div className="flex items-center gap-2 mb-6">
              <Users className="size-6 text-purple-400" />
              <h2 className="text-3xl font-display text-white">Community Interviews</h2>
            </div>
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
              {/* Sample community interviews */}
              <Card className="p-6 bg-slate-800/50 border-purple-500/20 animate-fade-in">
                <CardHeader>
                  <CardTitle className="text-white text-lg">Frontend Developer</CardTitle>
                  <CardDescription className="text-gray-300">
                    Technical • Intermediate • 8 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-white"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>

              <Card className="p-6 bg-slate-800/50 border-purple-500/20 animate-fade-in">
                <CardHeader>
                  <CardTitle className="text-white text-lg">Product Manager</CardTitle>
                  <CardDescription className="text-gray-300">
                    Behavioral • Advanced • 10 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-white"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>

              <Card className="p-6 bg-slate-800/50 border-purple-500/20 animate-fade-in">
                <CardHeader>
                  <CardTitle className="text-white text-lg">Data Scientist</CardTitle>
                  <CardDescription className="text-gray-300">
                    Technical • Beginner • 6 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500 text-purple-400 hover:bg-purple-500 hover:text-white"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}